14: import org.springframework.security.config.annotation.method.configuration.EnableGlobalMethodSecurity;
15: import org.springframework.security.config.annotation.web.builders.HttpSecurity;
16: import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
17: import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
18: import org.springframework.security.config.http.SessionCreationPolicy;
19: import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
20: import org.springframework.security.crypto.password.PasswordEncoder;
21: import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
22: 
23: @Configuration
24: @EnableWebSecurity
25: @EnableGlobalMethodSecurity(
26: 		securedEnabled = true,
27: 		jsr250Enabled = true,
28: 		prePostEnabled = true)
29: public class SecutiryConfig extends WebSecurityConfigurerAdapter {
30: 	private final CustomUserDetailsServiceImpl customUserDetailsService;
31: 	private final JwtAuthenticationEntryPoint unauthorizedHandler;
32: 	private final JwtAuthenticationFilter jwtAuthenticationFilter;
33: 
34: 	@Autowired
35: 	public SecutiryConfig(UserRepository userRepository, CustomUserDetailsServiceImpl customUserDetailsService,
36: 			JwtAuthenticationEntryPoint unauthorizedHandler, JwtAuthenticationFilter jwtAuthenticationFilter) {
37: 		this.customUserDetailsService = customUserDetailsService;
38: 		this.unauthorizedHandler = unauthorizedHandler;
39: 		this.jwtAuthenticationFilter = jwtAuthenticationFilter;
40: 	}
41: 
42: 	@Override
43: 	protected void configure(HttpSecurity http) throws Exception {
44: 
45: 		http.cors().and().csrf().disable()
46: 				.exceptionHandling()
47: 				.authenticationEntryPoint(unauthorizedHandler)
48: 				.and()
49: 				.sessionManagement()
50: 				.sessionCreationPolicy(SessionCreationPolicy.STATELESS)
51: 				.and()
52: 				.authorizeRequests()
53: 				.antMatchers(HttpMethod.GET, "/blogapi.json").permitAll()
54: 				.antMatchers(HttpMethod.GET, "/api/**").permitAll()
55: 				.antMatchers(HttpMethod.POST, "/api/auth/**").permitAll()
56: 				.antMatchers(HttpMethod.GET, "/api/users/checkUsernameAvailability", "/api/users/checkEmailAvailability").permitAll()
57: 				.anyRequest().authenticated();
58: 
59: 		http.addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);
60: 
61: 	}
62: 
63: 	public void configure(AuthenticationManagerBuilder authenticationManagerBuilder) throws Exception {
64: 		authenticationManagerBuilder.userDetailsService(customUserDetailsService)
65: 				.passwordEncoder(passwordEncoder());
66: 	}
67: 
68: 	@Bean(BeanIds.AUTHENTICATION_MANAGER)
69: 	public AuthenticationManager authenticationManagerBean() throws Exception {
70: 		return super.authenticationManagerBean();
71: 	}
72: 
73: 	@Bean
74: 	public PasswordEncoder passwordEncoder() {
75: 		return new BCryptPasswordEncoder();
76: 	}
77: }

