92: 		User user = userRepository.getUser(currentUser);
93: 		if (album.getUser().getId().equals(user.getId()) || currentUser.getAuthorities()
94: 				.contains(new SimpleGrantedAuthority(RoleName.ROLE_ADMIN.toString()))) {
95: 			album.setTitle(newAlbum.getTitle());
