59: 		if (albums.getNumberOfElements() == 0) {
60: 			return new PagedResponse<>(Collections.emptyList(), albums.getNumber(), albums.getSize(), albums.getTotalElements(),
61: 					albums.getTotalPages(), albums.isLast());
62: 		}
63: 
64: 		List<AlbumResponse> albumResponses = Arrays.asList(modelMapper.map(albums.getContent(), AlbumResponse[].class));
65: 
66: 		return new PagedResponse<>(albumResponses, albums.getNumber(), albums.getSize(), albums.getTotalElements(), albums.getTotalPages(),
67: 				albums.isLast());
68: 	}
