46: 
47:             // address, if set
48:             if (user.getAddress() != null) {
49:                 this.addressDTO = new AddressDTO(user.getAddress());
50:             }
51: 
52:             // Because the permissions can be associated to more than one roles i'm creating two String arrays
53:             // with the distinct keys of roles and permissions.
54:             roles = new ArrayList<>();
55:             permissions = new ArrayList<>();
