28:     public Permission getPermissionByKey(String key) {
29:         if (Strings.isNullOrEmpty(key)) {
30:             throw new InvalidPermissionDataException("Permission key cannot be null or empty");
31:         }
32:         Optional<Permission> userOpt = permissionRepository.findByPermission(key);
33:         if (userOpt.isPresent()) {
34:             return userOpt.get();
35:         }
36:         throw new PermissionNotFoundException(String.format("Permission not found for permission key = %s", key));
37:     }
