39:     @Transactional
40:     public Permission createPermission(PermissionDTO permissionDTO) {
41:         if (permissionDTO == null) {
42:             throw new InvalidPermissionDataException("Permission data cannot be null or empty");
43:         }
44: 
45:         String permissionKey = permissionDTO.getPermission();
46: 
47:         if (Strings.isNullOrEmpty(permissionKey)) {
48:             throw new InvalidPermissionDataException("Permission key cannot be null or empty");
49:         }
50: 
51:         // check permission
52:         Optional<Permission> permissionOpt = permissionRepository.findByPermission(permissionKey);
53:         if (permissionOpt.isPresent()) {
54:             throw new PermissionNotFoundException(String.format("Permission %s already existing with the same key with Id = %s",
55:                     permissionKey, permissionOpt.get().getId()));
56:         }
57: 
58:         Permission permission = new Permission();
59:         permission.setPermission(permissionKey);
60: 
61:         permission.setNote(permissionDTO.getNote());
62:         permission.setEnabled(permissionDTO.isEnabled());
63: 
64:         Permission createdPermission = permissionRepository.save(permission);
65: 
66:         log.info(String.format("Created permission %s with Id = %s", permissionKey, createdPermission.getId()));
67:         return createdPermission;
