72:         if (permissionDTO == null) {
73:             throw new InvalidPermissionDataException("Permission data cannot be null");
74:         }
75: 
76:         Long permissionId = permissionDTO.getId();
77:         Optional<Permission> permissionOpt = permissionRepository.findById(permissionId);
78:         if (!permissionOpt.isPresent()) {
79:             throw new PermissionNotFoundException(String.format("The permission with the id = %s has not been found",
80:                     permissionId));
81:         }
82: 
83:         Permission permission = permissionOpt.get();
84:         String permissionKey = permissionDTO.getPermission();
85: 
86:         // check if exists a different configuration with the same permissionKey
87:         Optional<Permission> permissionByKeyOpt = permissionRepository.findByPermission(permissionKey);
88:         if (permissionByKeyOpt.isPresent()) {
89:             Permission permission1 = permissionByKeyOpt.get();
90:             if (!permission1.getId().equals(permission.getId())) {
91:                 throw new InvalidPermissionDataException(String.format("Exists already a permission with the key %s." +
92:                         " Use another key", permissionKey));
93:             }
94:         }
95: 
96:         // update permission
97:         permission.setPermission(permissionDTO.getPermission());
98:         permission.setEnabled(permissionDTO.isEnabled());
99:         permission.setNote(permissionDTO.getNote());
100: 
