2: 
3: import com.giassi.microservice.demo2.rest.users.exceptions.InvalidConfigurationException;
4: import com.google.common.base.Strings;
5: 
6: import javax.crypto.SecretKeyFactory;
7: import javax.crypto.spec.PBEKeySpec;
8: import java.security.NoSuchAlgorithmException;
9: import java.security.SecureRandom;
10: import java.security.spec.InvalidKeySpecException;
11: import java.util.Arrays;
12: import java.util.Base64;
13: import java.util.Random;
14: 
15: /**
16:  * Provides a set of methods to encrypt or decrypt a String information.
17:  *
18:  * See {@http://www.appsdeveloperblog.com/ http://www.appsdeveloperblog.com/encrypt-user-password-example-java/}
19:  *
20:  */
21: public class EncryptionService {
22: 
23:     public static final String ALGORITHM = "PBKDF2WithHmacSHA1";
24:     public static final int KEY_LENGTH = 256;
25: 
26:     // demo salt for testing or first setup purpose
27:     public static final String DEFAULT_SALT = "WZeBXmCI9cAz3LyY9Sdllj9l5iPsXC";
28: 
29:     private static final Random RANDOM = new SecureRandom();
30:     private static final String ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
31:     private static final int ITERATIONS = 10000;
32: 
33:     public static String generateSalt(int length) {
34:         StringBuilder saltStr = new StringBuilder(length);
35:         for (int i = 0; i < length; i++) {
36:             saltStr.append(ALPHABET.charAt(RANDOM.nextInt(ALPHABET.length())));
37:         }
38:         return new String(saltStr);
39:     }
40: 
41:     public static byte[] hash(char[] password, byte[] salt) {
42:         PBEKeySpec spec = new PBEKeySpec(password, salt, ITERATIONS, KEY_LENGTH);
43:         Arrays.fill(password, Character.MIN_VALUE);
44:         try {
45:             SecretKeyFactory skf = SecretKeyFactory.getInstance(ALGORITHM);
46:             return skf.generateSecret(spec).getEncoded();
47:         } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
48:             throw new AssertionError("Error while hashing a password: " + e.getMessage(), e);
49:         } finally {
50:             spec.clearPassword();
51:         }
52:     }
53: 
54:     public static String encrypt(String password, String salt) {
55:         if (Strings.isNullOrEmpty(salt)) {
56:             throw new InvalidConfigurationException("Invalid salt: Wrong configuration. Salt cannot be empty or null");
57:         }
58:         byte[] securePassword = hash(password.toCharArray(), salt.getBytes());
59:         return Base64.getEncoder().encodeToString(securePassword);
60:     }
61: 
62:     public static boolean isPasswordValid(String providedPassword,
63:                                           String securedPassword, String salt)
64:     {
65:         // Generate new secure password with the same salt
66:         String newSecurePassword = encrypt(providedPassword, salt);
67:         // Check if the passwords are equal
68:         return newSecurePassword.equalsIgnoreCase(securedPassword);
69:     }
70: 
71: }

