59:                 for (Permission p : role.getPermissions()) {
60:                     String key = p.getPermission();
61:                     if ((!permissions.contains(key)) && (p.isEnabled())) {
62:                         // add the permission only if enabled
63:                         permissions.add(key);
64:                     }
