1: package com.giassi.microservice.demo2.rest.users.dtos;
2: 
3: import com.giassi.microservice.demo2.rest.users.entities.Permission;
4: import com.giassi.microservice.demo2.rest.users.entities.Role;
5: import com.giassi.microservice.demo2.rest.users.entities.User;
6: import lombok.Data;
7: 
8: import java.io.Serializable;
9: import java.time.LocalDateTime;
10: import java.util.ArrayList;
11: import java.util.List;
12: 
13: @Data
14: public class UserDTO implements Serializable {
15: 
16:     public UserDTO() {
17:         // empty constructor
18:         roles = new ArrayList<>();
19:         permissions = new ArrayList<>();
20:     }
21: 
22:     public UserDTO(User user) {
23:         if (user != null) {
24:             this.id = user.getId();
25:             this.username = user.getUsername();
26:             this.name = user.getName();
27:             this.surname = user.getSurname();
28:             this.gender = user.getGender().name();
29: 
30:             this.birthDate = user.getBirthDate();
31: 
32:             this.enabled = user.isEnabled();
33: 
34:             this.note = user.getNote();
35: 
36:             this.creationDt = user.getCreationDt();
37:             this.updatedDt = user.getUpdatedDt();
38:             this.loginDt = user.getLoginDt();
39: 
40:             this.secured = user.isSecured();
41: 
42:             // contact, if set
43:             if (user.getContact() != null) {
44:                 this.contactDTO = new ContactDTO(user.getContact());
45:             }
46: 
47:             // address, if set
48:             if (user.getAddress() != null) {
49:                 this.addressDTO = new AddressDTO(user.getAddress());
50:             }
51: 
52:             // Because the permissions can be associated to more than one roles i'm creating two String arrays
53:             // with the distinct keys of roles and permissions.
54:             roles = new ArrayList<>();
55:             permissions = new ArrayList<>();
56: 
57:             for (Role role : user.getRoles()) {
58:                 roles.add(role.getRole());
59:                 for (Permission p : role.getPermissions()) {
60:                     String key = p.getPermission();
61:                     if ((!permissions.contains(key)) && (p.isEnabled())) {
62:                         // add the permission only if enabled
63:                         permissions.add(key);
64:                     }
65:                 }
66:             }
67: 
68:         }
69:     }
